from pathlib import Path
import json,hashlib,struct,html
R=Path(__file__).absolute().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,v):(R/p).write_text(json.dumps(v,indent=2),encoding='utf-8')
m=json.loads((R/'manifest.json').read_text());glb=R/'runtime/lwf_barn_stage_v1.glb';b=glb.read_bytes();n=struct.unpack_from('<I',b,12)[0];d=json.loads(b[20:20+n])
m.update({'status':'Ready for coordinator inspection and authorized Builder integration','runtime_file':str(glb.relative_to(R)),'runtime_sha256':sha(glb),'runtime_bytes':len(b),'triangles':sum(q['triangles'] for q in m['nodes']),'mesh_count':len(d['meshes']),'source_file':'source/lwf_barn_stage_v1.blend','source_output_sha256':sha(R/'source/lwf_barn_stage_v1.blend'),'anchors':'anchors.json','roof_footprint_unchanged':True})
fades=['Barn_Roof','Barn_WallFade','Barn_DoorFade','Barn_TrussFade']
for mat in d['materials']:
 if mat['name'] in fades:assert not mat.get('doubleSided',False),mat['name']
assert not json.loads((R/'verification/geometry.json').read_text())['failures']
save('manifest.json',m)
save('visibility-contract.json',{'fade_materials':fades,'alpha':.3,'fade_seconds':.25,'empty_hold_seconds':1,'restore_seconds':.5,'trigger':'any relevant person inside actual interior OR selected','cull_mode':'BACK — preserve exported flag; do not apply marquee CULL_DISABLED override','shadow':'opaque shadow-only twins for fade nodes; preserve floor/frames/sign/people/kit opaque','default':'all exported surfaces opaque','node_material_mapping':{q['name']:q['materials'] for q in m['nodes']},'not_implemented_here':['occupancy','selection','shadow twin creation','timers','navigation','weather shelter']})
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Barn Stage — built asset review</title><style>body{font:17px/1.55 system-ui;background:#f5f0df;color:#203f35;max-width:1380px;margin:32px auto;padding:0 24px}h1{font:54px Georgia;margin:0}h2{font:30px Georgia;margin-top:38px}p{max-width:950px}a{color:#256253}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}figure{margin:0}img{display:block;width:100%;border-radius:8px}figcaption{font-size:14px;padding:8px 0;color:#53685b}.note{padding:18px;background:#e1e8d7}summary{cursor:pointer;font-weight:600;padding:14px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><h1>Barn Stage</h1><p>Approved gable-end layout, built from the existing large barn. Original footprint and exterior character retained; flush interior floor, two usable long-side entrances and separate fade groups. Existing riser and performance kit are reused by instance transforms.</p><p class="note"><strong>Ready for coordinator inspection and authorized Builder integration.</strong> No new art approval gate. Band backs to the short east gable, facing west down the long hall. No tier, capacity, economy or gameplay decisions made.</p><p><a href="HANDOFF.txt">Builder handoff</a> · <a href="anchors.json">Access and kit anchors</a> · <a href="visibility-contract.json">Visibility contract</a> · <a href="manifest.json">Asset manifest</a></p><h2>Actual exported asset · native Godot views</h2><p>Solid / occupied pairs at orthographic size 26, framing the whole barn. Exact four game camera directions. Occupied views use 30% alpha, opaque shadow twins and back-face culling. These are isolated asset renders with staged people and lighting, not integrated game captures.</p>'''
dirs=['South · yaw 45°','West · yaw 135°','North · yaw 225°','East · yaw 315°']
def fig(name,caption):
 assert (R/'review'/name).exists(),name
 return '<figure><a href="review/'+name+'"><img loading="lazy" src="review/'+name+'" alt="'+html.escape(caption)+'"></a><figcaption>'+html.escape(caption)+'</figcaption></figure>'
for i,label in enumerate(dirs):page+='<h3>'+label+'</h3><div class="grid">'+fig(f'native-solid-{i}.png','Empty / solid shell')+fig(f'native-faded-{i}.png','Occupied / roof, walls, doors and trusses translucent')+'</div>'
page+='<p class="note">Preserve the barn’s exported back-face culling when adapting RoofFade. The marquee forces double-sided rendering; that made the original layered slate and masonry unnecessarily opaque. The retained layers still produce lines and overlapping tint, as shown here. Final in-game rain/low-light, occupancy, clicking and navigation checks belong to Builder.</p>'
for zoom,label in [(18,'Closest game zoom · size 18'),(62,'Default game zoom · size 62')]:
 page+='<details><summary>'+label+'</summary><p>Inspection focus (0,3.5,0). Size 18 can crop the tall roof; default zoom makes the people small. These are real scale differences, not enlarged character overlays.</p><div class="grid">'
 for i,direction in enumerate(dirs):
  for mode in ['solid','faded']:page+=fig(f'native-{mode}-{i}-zoom{zoom}.png',direction+' · '+mode)
 page+='</div></details>'
page+='<h2>Supplemental Blender views</h2><div class="grid">'+fig('solid-0.png','Exported barn · solid')+fig('faded-end.png','Actual kit facing lengthways · Blender lighting')+'</div>'
page+='''<h2>Practical adaptations</h2><p>The existing left parked oak leaf would cover the new exit. It is now a compact folded pair; the 2 m exit sits at X −8.65..−6.65 on the long front wall. The 7.8 m main opening stays clear. The old raised slab and step have been replaced with a floor at Y=0. The riser’s separate stair rotates 180° on this instance, while the original asset and corner rails remain unchanged.</p><h2>Verification</h2><p>136 doorway samples, 50 floor samples, performer deck heights and all five stair treads passed on reimported geometry. Stair and corner rails have no triangle intersections. Native import confirms 19 mesh surfaces and the expected materials. The exterior X/Z bounds and roof height match the original barn.</p><p><a href="verification/geometry.json">Geometry results</a> · <a href="verification/native-import.json">Native import</a> · <a href="references/02-end-on-hall-v2-gable-facing.png">Approved concept</a> · <a href="PROVENANCE-sha256.json">Provenance</a></p><p>Reproduction scripts and editable Blender source are included. The runtime GLB contains only the barn; people, instruments, riser, review lights and environment are separate references.</p></html>'''
(R/'review.html').write_text(page,encoding='utf-8')
(R/'CURRENT-TASK.txt').write_text('COMPLETE: Barn Stage approved asset adaptation delivered. Ready for coordinator inspection and already-authorized Builder integration. No extra aesthetic approval gate. No gameplay/tier/capacity/economy changes.\n')
save('PROVENANCE-sha256.json',{'files':{str(p.relative_to(R)).replace('\\','/'):sha(p) for p in sorted(R.rglob('*')) if p.is_file() and '.godot' not in p.parts and p.name!='PROVENANCE-sha256.json' and p.suffix!='.blend1'}})
print('PACKAGE READY',m['triangles'],'triangles',m['runtime_bytes'],'bytes')
